<template><view class="page">
  <view class="appbar"><view><text class="hello">晚上好，演示员工</text><text class="sub">{{today}} · HOLE CLUB</text></view><button class="role" @click="showRoles=true">{{roleName[role]}}⌄</button></view>
  <view class="notice"><text class="dot"></text><text>今晚营业中</text><span>预计高峰 22:30</span></view>
  <view class="metric-grid"><view class="metric accent"><text>今日订台</text><b>{{orders.length}}</b><span>较昨日 +2</span></view><view class="metric"><text>待到店</text><b>{{reserved}}</b><span>及时联系客户</span></view><view class="metric"><text>消费中</text><b>{{serving}}</b><span>现场服务中</span></view><view class="metric"><text>今日销售额</text><b class="money">¥{{revenue}}</b><span>线下收款统计</span></view></view>
  <view class="section-head"><b>快捷操作</b><span>常用功能</span></view>
  <view class="actions"><view @click="go('/pages/booking/index')"><text class="icon green">＋</text><b>创建预订</b><span>选台并录入客户</span></view><view @click="go('/pages/tables/index')"><text class="icon blue">▦</text><b>实时台位</b><span>查看全场状态</span></view><view @click="go('/pages/orders/index')"><text class="icon orange">≡</text><b>订单管理</b><span>开台、加单、结账</span></view></view>
  <view class="section-head"><b>今日动态</b><span @click="go('/pages/orders/index')">查看全部 ›</span></view>
  <view class="timeline"><view v-for="order in orders.slice(0,3)" :key="order.id" class="timeline-row"><text :class="['state',order.status]">{{statusText[order.status]}}</text><view><b>{{order.tableId}} · {{order.customerName}}</b><span>{{order.arrivalTime}} 到店 · {{order.guestCount}}人 · {{order.salesName}}</span></view><text class="amount">¥{{total(order)}}</text></view></view>
  <view v-if="role==='owner'" class="ranking"><view class="section-head"><b>销售排行榜</b><span>今日</span></view><view class="rank"><b>1</b><text>销售 A</text><span>2 台 · ¥6,760</span></view><view class="rank"><b>2</b><text>销售 B</text><span>1 台 · ¥576</span></view></view>
  <view class="tabbar"><view class="active"><text>⌂</text><span>工作台</span></view><view @click="go('/pages/tables/index')"><text>▦</text><span>台位</span></view><view @click="go('/pages/orders/index')"><text>≡</text><span>订单</span></view><view @click="coming"><text>◎</text><span>客户</span></view><view @click="coming"><text>○</text><span>我的</span></view></view>
  <view v-if="showRoles" class="mask" @click="showRoles=false"><view class="sheet" @click.stop><view class="handle"></view><b>切换演示角色</b><button v-for="(name,key) in roleName" :key="key" :class="{active:role===key}" @click="changeRole(key as Role)"><text>{{name}}</text><span>{{role===key?'当前角色':'切换'}}</span></button></view></view>
</view></template>
<script setup lang="ts">
import{computed,ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{currentRole,setRole,roleName,getOrders,total,type Role,type ClubOrder,type OrderStatus}from'../../services/orders'
const orders=ref<ClubOrder[]>([]),role=ref<Role>(currentRole()),showRoles=ref(false);onShow(()=>orders.value=getOrders())
const today=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'short'}),reserved=computed(()=>orders.value.filter(o=>o.status==='reserved').length),serving=computed(()=>orders.value.filter(o=>['arrived','serving'].includes(o.status)).length),revenue=computed(()=>orders.value.reduce((s,o)=>s+total(o),0).toLocaleString())
const statusText:Record<OrderStatus,string>={reserved:'待到店',arrived:'已到店',serving:'消费中',cleaning:'待清台',completed:'已完成',cancelled:'已取消'}
const go=(url:string)=>uni.navigateTo({url}),coming=()=>uni.showToast({title:'下一阶段开放',icon:'none'});const changeRole=(r:Role)=>{role.value=r;setRole(r);showRoles.value=false}
</script>
<style scoped>
.page{min-height:100vh;background:#f5f5f5;color:#191919;padding:0 16px 86px}.appbar{height:82px;display:flex;align-items:center;justify-content:space-between}.hello{display:block;font-size:22px;font-weight:700}.sub{display:block;color:#8b8b8b;font-size:11px;margin-top:4px}.role{margin:0;background:#fff;color:#252525;border-radius:17px;padding:0 13px;height:34px;line-height:34px;font-size:12px;box-shadow:0 2px 12px rgba(0,0,0,.05)}.notice{height:40px;background:#eaf8ee;border-radius:9px;padding:0 12px;display:flex;align-items:center;font-size:11px;color:#16833b}.notice .dot{width:7px;height:7px;border-radius:50%;background:#07c160;margin-right:7px}.notice span{margin-left:auto;color:#6f8a76}.metric-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}.metric{height:113px;background:#fff;border-radius:12px;padding:15px;box-shadow:0 3px 14px rgba(0,0,0,.035)}.metric.accent{background:#07c160;color:#fff}.metric text,.metric b,.metric span{display:block}.metric text{font-size:11px;opacity:.68}.metric b{font-size:29px;margin-top:7px}.metric b.money{font-size:21px;margin-top:13px}.metric span{font-size:9px;margin-top:4px;opacity:.6}.section-head{display:flex;align-items:center;justify-content:space-between;margin:24px 2px 11px}.section-head b{font-size:16px}.section-head span{font-size:10px;color:#999}.actions{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.actions>view{height:125px;background:#fff;border-radius:11px;padding:13px;display:flex;flex-direction:column}.icon{width:35px;height:35px;border-radius:9px;display:flex;align-items:center;justify-content:center;font-size:21px}.green{background:#e8f8ed;color:#07c160}.blue{background:#eaf3ff;color:#3478f6}.orange{background:#fff1e8;color:#ff7d24}.actions b{font-size:12px;margin-top:auto}.actions span{font-size:8px;color:#9a9a9a;margin-top:4px}.timeline{background:#fff;border-radius:12px;padding:2px 14px}.timeline-row{min-height:72px;display:flex;align-items:center;border-bottom:1px solid #f0f0f0}.timeline-row:last-child{border:0}.state{width:47px;height:24px;border-radius:5px;background:#fff4dc;color:#dc8b00;display:flex;align-items:center;justify-content:center;font-size:9px;margin-right:10px}.state.arrived,.state.serving{background:#e7f5ff;color:#2178c4}.timeline-row view{flex:1}.timeline-row b,.timeline-row span{display:block}.timeline-row b{font-size:12px}.timeline-row span{font-size:9px;color:#999;margin-top:5px}.amount{font-size:12px;font-weight:600}.ranking{margin-top:5px}.rank{height:52px;background:#fff;border-bottom:1px solid #eee;display:flex;align-items:center;padding:0 14px}.rank:first-of-type{border-radius:10px 10px 0 0}.rank:last-child{border-radius:0 0 10px 10px}.rank b{color:#f3a307;width:26px}.rank text{font-size:12px}.rank span{margin-left:auto;color:#888;font-size:10px}.tabbar{position:fixed;left:50%;bottom:0;transform:translateX(-50%);width:min(480px,100%);height:68px;background:rgba(255,255,255,.97);border-top:1px solid #ededed;display:grid;grid-template-columns:repeat(5,1fr);z-index:5}.tabbar view{display:flex;flex-direction:column;align-items:center;justify-content:center;color:#929292;font-size:17px}.tabbar span{font-size:9px;margin-top:3px}.tabbar .active{color:#07c160}.mask{position:fixed;inset:0;z-index:20;background:rgba(0,0,0,.36);display:flex;align-items:end;justify-content:center}.sheet{width:min(480px,100%);background:#fff;border-radius:16px 16px 0 0;padding:10px 18px 28px}.handle{width:34px;height:4px;background:#ddd;border-radius:5px;margin:0 auto 18px}.sheet>b{display:block;font-size:16px;margin-bottom:10px}.sheet button{margin:0;width:100%;height:49px;background:#fff;border-top:1px solid #eee;border-radius:0;display:flex;align-items:center;justify-content:space-between;font-size:13px}.sheet button span{font-size:10px;color:#aaa}.sheet button.active text,.sheet button.active span{color:#07c160}
</style>
